import re

def slugify(text, max_len=40):
    """Lowercase, words joined by single hyphens, trimmed to max_len without a trailing hyphen."""
    s = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    s = s[:max_len + 1]
    return s.rstrip("-")
EOF
